-- RID=1447 | MENU=3 | ITEM=1 | RQUERY=1 | NAME=Laporan Daftar Kunjungan | FILE=kunjunganglobal
SELECT kj.kjtgl, kj.kjnotransaksi , kj.kjnopasien, YEAR(kj.kjtglkeluar) AS a , kj.kjtglkeluar , YEAR(kj.kjtglmeninggal) AS b , kj.kjtglmeninggal , CASE kj.kjcarakunjungan WHEN 1 THEN 'Datang Sendiri' WHEN 2 THEN 'Rujukan' END AS kjcarakunjungan , r.rnama AS kjdirujukoleh , i.inama AS kjditanggungoleh , st.nama AS kjstatus , p.pnama AS namapasien , p.palamat AS alamatpasien , CONCAT(p.pkeluargalain," ",p.pnoteleponlain) AS keluargapasien, p.ptgllahir , CASE p.pjeniskelamin WHEN "P" THEN "Perempuan" WHEN "L" THEN "Laki - Laki" END AS pjeniskelamin, p.pnohp FROM m_11_kj kj JOIN m0_status st ON kj.kjstatus = st.kode LEFT JOIN m1_reference r ON kj.kjdirujukoleh = r.rid LEFT JOIN m1_insurer i ON kj.kjditanggungoleh = i.iid LEFT JOIN m1_patient p ON kj.kjnopasien = p.pkode ORDER BY kj.kjnotransaksi;

-- RID=1396 | MENU=3 | ITEM=3 | RQUERY=1 | NAME=Kwitansi | FILE=kunjungankwitansi
SELECT kj.kjnotransaksi , p.pnama , p.pprefix , u.ukode AS ukode, u.unama AS unama FROM m_11_kj kj JOIN m1_patient p ON kj.kjnopasien = p.pkode JOIN m0_user u ON kj.kjinputuser = u.userid ORDER BY kj.kjnotransaksi;

-- RID=1684 | MENU=3 | ITEM=5 | RQUERY=1 | NAME=Daftar Asuransi Kunjungan | FILE=kunjungan
SELECT kj.kjtgl , kj.kjnotransaksi , kj.kjnopasien , kj.kjnama , kj.kjditanggungoleh , i.inama AS asuransi , kj.kjtglkeluar , YEAR(kj.kjtglkeluar) AS tahun FROM m_11_kj kj LEFT JOIN m1_insurer i ON kj.kjditanggungoleh = i.iid ORDER BY kj.kjtgl ASC;

-- RID=1397 | MENU=4 | ITEM=1 | RQUERY=1 | NAME=Daftar Layanan Umum | FILE=layananumumglobal
SELECT kj.kjnotransaksi , kj.kjtgl , lu.lunotransaksi , lu.lutgl , st.nama , kj.kjnopasien, kj.kjnama , ic.icnama AS jenis , b.bkode , lud.namalayanan, lud.jml , lud.satuan , lud.diskon , lud.harga , ((lud.jml * lud.harga) - lud.jmldiskon) AS total , userr.ukode AS usernama , lud.namadokter FROM m_11_lu lu JOIN m_11_kj kj ON lu.luidkj = kj.kjid JOIN m0_status st ON lu.lustatus = st.kode JOIN m_11_lu_detail lud ON lu.luid = lud.idlu JOIN m1_item_category ic ON lud.jenis = ic.ickode JOIN m1_item b ON lud.idlayanan = b.bid JOIN m0_user userr ON lu.luinputuser = userr.userid ORDER BY lu.luid , lud.urutan;

-- RID=1398 | MENU=4 | ITEM=2 | RQUERY=1 | NAME=Layanan Umum | FILE=layananumum
SELECT kj.kjnotransaksi , kj.kjtgl , lu.lunotransaksi , lu.lutgl , st.nama , kj.kjnopasien, kj.kjnama , ic.icnama AS jenis , b.bkode , lud.namalayanan, lud.jml , lud.satuan , lud.diskon , lud.harga , ((lud.jml * lud.harga) - lud.jmldiskon) AS total , userr.ukode AS usernama , lud.namadokter FROM m1_room r JOIN m1_bed b ON r.rnama = b.bkamar ORDER BY lu.luid , lud.urutan;

-- RID=1399 | MENU=5 | ITEM=1 | RQUERY=1 | NAME=Daftar Laboraturium | FILE=laboraturiumglobal
SELECT userrr.ukode AS usrenama , lb.lbnotransaksi , lb.lbtgl , kj.kjnotransaksi , kj.kjtgl , st.nama , p.pkode , p.pnama , ic.icnama , b.bkode , lbd.namalayanan , lbd.jml , lbd.satuan , lbd.diskon , lbd.harga , ((lbd.jml * lbd.harga) - lbd.jmldiskon) AS total , lbd.namadokter FROM m_11_lb lb JOIN m_11_kj kj ON lb.lbidkj = kj.kjid JOIN m1_patient p ON kj.kjnopasien = p.pkode JOIN m0_status st ON lb.lbstatus = st.kode JOIN m_11_lb_detail lbd ON lb.lbid = lbd.idlb JOIN m1_item b ON lbd.idlayanan = b.bid JOIN m0_user userrr ON lb.lbinputuser = userrr.userid LEFT JOIN m1_item_category ic ON lbd.jenis = ic.ickode ORDER BY lb.lbidkj , lb.lbid , lbd.urutan;

-- RID=1400 | MENU=5 | ITEM=2 | RQUERY=1 | NAME=Laboratorium | FILE=laboraturium
SELECT userrr.ukode AS usrenama , lb.lbnotransaksi , lb.lbtgl , kj.kjnotransaksi , kj.kjtgl , st.nama , p.pkode , p.pnama , ic.icnama , b.bkode , lbd.namalayanan , lbd.jml , lbd.satuan , lbd.diskon , lbd.harga , ((lbd.jml * lbd.harga) - lbd.jmldiskon) AS total , lbd.namadokter FROM m_11_lb lb JOIN m_11_kj kj ON lb.lbidkj = kj.kjid JOIN m1_patient p ON kj.kjnopasien = p.pkode JOIN m0_status st ON lb.lbstatus = st.kode JOIN m_11_lb_detail lbd ON lb.lbid = lbd.idlb JOIN m1_item_category ic ON lbd.jenis = ic.ickode JOIN m1_item b ON lbd.idlayanan = b.bid JOIN m0_user userrr ON lb.lbinputuser = userrr.userid ORDER BY lb.lbidkj , lb.lbid , lbd.urutan;

-- RID=1401 | MENU=5 | ITEM=3 | RQUERY=1 | NAME=Hasil Laboraturium | FILE=laboraturium2
SELECT lb.lbid , pc.pcnama AS lbkategoripasien , kj.kjnopasien , kj.kjnama , CASE lb.lbjenislab WHEN "LL" THEN "Lab Luar" WHEN "LD" THEN "Lab Dalam" END AS lbjenislab , CASE lb.lbperawatan WHEN "RJ" THEN "Rawat Jalan" WHEN "RI" THEN "Rawat Inap" END AS lbperawatan , lb.lbtgl , lb.lbnotransaksi , kj.kjnotransaksi , k.knama AS lbdokter , lb.lbkamar FROM m_11_lb lb JOIN m1_patient_category pc ON lb.lbkategoripasien = pc.pckode LEFT JOIN m_11_kj kj ON lb.lbidkj = kj.kjid LEFT JOIN m1_contact k ON lb.lbdokter = k.kkode ORDER BY lb.lbid;

-- RID=1570 | MENU=5 | ITEM=4 | RQUERY=1 | NAME=Daftar Laboraturium  | FILE=DaftarLaboraturium
SELECT lb.lbtgl , lb.lbnotransaksi , kj.kjnopasien , kj.kjnama , SUM(lbd.jml * lbd.harga) AS total , (SUM(lbd.jml * lbd.harga) * 0.1 ) AS JP, CASE lb.lbperawatan WHEN "RI" THEN "Rawat Inap" WHEN "RJ" THEN "Rawat Jalan" END AS lbperawatan , pc.pcnama AS lbkategoripasien FROM m_11_lb lb JOIN m_11_lb_detail lbd on lb.lbid = lbd.idlb LEFT JOIN m_11_kj kj ON lb.lbidkj = kj.kjid LEFT JOIN m1_patient_category pc ON lb.lbkategoripasien = pc.pckode WHERE (lb.lbstatus = 2 OR lb.lbstatus = 3 OR lb.lbstatus = 4 OR lb.lbstatus = 7) GROUP BY lb.lbid ORDER BY lb.lbid;

-- RID=1571 | MENU=5 | ITEM=5 | RQUERY=1 | NAME=Pemerikasaan Laboratorium | FILE=PemerikasaanLaboratorium
SELECT b.bid , b.bkode , b.bnama , lbd.namalayanan , lb.lbtgl , YEAR(lb.lbtgl) AS tahun , day(lb.lbtgl) AS tanggal , CASE lb.lbperawatan WHEN "RI" THEN "Rawat Inap" WHEN "RJ" THEN "Rawat Jalan" END AS lbperawatan , pc.pcnama AS lbkategoripasien FROM m1_item b LEFT JOIN m_11_lb_detail lbd ON lbd.idlayanan = b.bid LEFT JOIN m_11_lb lb ON lbd.idlb = lb.lbid LEFT JOIN m1_patient_category pc ON lb.lbkategoripasien = pc.pckode WHERE b.bkategori = "Lab" ORDER BY b.bid , day(lb.lbtgl) ASC;

-- RID=1573 | MENU=5 | ITEM=6 | RQUERY=1 | NAME=CN | FILE=CN
SELECT lb.lbtgl , lb.lbnotransaksi , CASE lb.lbpenjualanlangsung WHEN 0 THEN p.pnama WHEN 1 THEN k.knama END AS pnama, lb.lbtotaltransaksi , kd.knama AS lbdokter FROM m_11_lb lb LEFT JOIN m1_patient p ON p.pid = lb.lbcustomer AND lb.lbpenjualanlangsung = 0 LEFT JOIN m1_contact k ON k.kid = lb.lbcustomer AND lb.lbpenjualanlangsung = 1 LEFT JOIN m1_contact kd ON lb.lbdokter = kd.kkode ORDER BY lb.lbid;

-- RID=1402 | MENU=6 | ITEM=1 | RQUERY=1 | NAME=Laporan Apotek  | FILE=apotek
SELECT ak.aknotransaksi , ak.aktgl , kj.kjnotransaksi, kj.kjtgl , kj.kjnopasien , kj.kjnama, b.bkode , akd.namalayanan , akd.jml , akd.satuan , akd.harga , akd.diskon , ((akd.jml * akd.harga) - akd.jmldiskon) AS total , ic.icnama AS jenis , u.ukode as usernama FROM m_11_ak ak JOIN m_11_ak_detail akd ON ak.akid = akd.idak JOIN m_11_kj kj ON akd.idkjdetail = kj.kjid JOIN m1_item_category ic ON akd.jenis = ic.ickode JOIN m1_item b ON akd.idlayanan = b.bid JOIN m0_user u ON ak.akinputuser = u.userid ORDER BY ak.aknotransaksi , kj.kjnotransaksi;

