SELECT ak.aknotransaksi , ak.aktgl , kj.kjnotransaksi, kj.kjtgl , kj.kjnopasien , kj.kjnama, b.bkode , akd.namalayanan , akd.jml , akd.satuan , akd.harga , akd.diskon , ((akd.jml * akd.harga) - akd.jmldiskon) AS total , ic.icnama AS jenis , u.ukode as usernama FROM m_11_ak ak JOIN m_11_ak_detail akd ON ak.akid = akd.idak LEFT JOIN m_11_kj kj ON ak.akidkj = kj.kjid JOIN m1_item b ON akd.idlayanan = b.bid LEFT JOIN m1_contact k ON ak.akpetugas = k.kid LEFT JOIN m1_contact kd ON ak.akdokter = kd.kkode LEFT JOIN m1_patient_category pc ON kj.kjkategoripasien = pc.pckode ORDER BY ak.aknotransaksi , kj.kjnotransaksi;

